const $=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:4}).format(n);
const items=[...new Set(recipes.map(r=>r.item))].sort();
items.forEach(item=>$('item').add(new Option(item,item)));$('item').add(new Option('Custom recipe…','custom'));$('item').value='Reinforced Iron Plate';
$('coverage').textContent=`${recipes.length} wiki recipes · ${items.length} items`;
function selectItem(){const custom=$('item').value==='custom';$('custom').hidden=!custom;$('recipe').disabled=custom;$('recipe').replaceChildren();recipes.filter(r=>r.item===$('item').value).forEach(r=>$('recipe').add(new Option(`${r.alternate?'Alternate: ':'Standard: '}${r.name}`,r.id)));if(custom)$('recipe').add(new Option('Enter a wiki recipe rate','custom'));render();}
function getRecipe(){return $('item').value==='custom'?{item:'Custom output',name:'Custom recipe',machine:$('customMachine').value,rate:Number($('base').value),inputs:{}}:recipes.find(r=>r.id===$('recipe').value);}
function calculate(rate,target,clock){if(!Number.isFinite(rate)||rate<=0||!Number.isFinite(target)||target<0||target>1e9||!Number.isFinite(clock)||clock<1||clock>250)throw Error('Enter a valid target (0–1 billion), a positive recipe rate, and a clock speed from 1% to 250%.');const per=rate*clock/100;const exact=target/per;const count=Math.ceil(exact-Number.EPSILON*Math.max(1,exact)*4);return{per,count,capacity:count*per,balanced:count?target/(count*rate)*100:0,target};}
function render(){try{if(!$('amount').value||!$('clock').value)throw Error('Enter your output target and clock speed.');const r=getRecipe(),batch=$('mode').value==='batch';$('timeField').hidden=!batch;$('amountLabel').textContent=batch?'Total items':'Items per minute';const minutes=Number($('minutes').value);if(batch&&(!Number.isFinite(minutes)||minutes<=0))throw Error('Enter a completion time greater than zero.');const clock=Number($('clock').value),target=Number($('amount').value)/(batch?minutes:1),v=calculate(r.rate,target,clock);$('error').textContent='';document.body.classList.remove('invalid');$('slider').value=clock;$('clockTag').textContent=clock>100?'OVERCLOCKED':clock<100?'UNDERCLOCKED':'STANDARD';document.querySelectorAll('[data-clock]').forEach(b=>b.classList.toggle('active',Number(b.dataset.clock)===clock));$('count').textContent=fmt(v.count);$('machine').textContent=r.machine+(v.count===1?'':'s');$('summary').textContent=`${fmt(target)} items / min requested · ${fmt(clock)}% clock speed`;$('perMachine').textContent=fmt(v.per);$('capacity').textContent=fmt(v.capacity);$('spare').textContent=fmt(Math.max(0,v.capacity-target));const util=v.capacity?target/v.capacity*100:0;$('util').textContent=fmt(util)+'%';$('bar').style.width=util+'%';$('recipeBadge').textContent=r.name==='Custom recipe'?'CUSTOM RECIPE':r.alternate?'ALTERNATE RECIPE':'STANDARD RECIPE';$('recipeNote').textContent=r.name==='Custom recipe'?'Use the output / min shown on the wiki at 100% clock.':`${r.machine} · ${fmt(r.rate)} items / min at 100%`;$('tuning').textContent=!v.count?'No machines are needed for a zero target.':v.balanced<1?'Your target is below 1% clock speed. Run one machine intermittently at the 1% minimum.':`Set all ${fmt(v.count)} ${r.machine.toLowerCase()}${v.count===1?'':'s'} to approximately ${fmt(v.balanced)}% clock speed to produce ${fmt(target)} items / min with no surplus.`;$('inputs').replaceChildren();Object.entries(r.inputs).forEach(([name,rate])=>{const row=document.createElement('div');row.className='input-row';const label=document.createElement('span');label.textContent=name;const value=document.createElement('strong');value.textContent=fmt(rate*target/r.rate)+' / min';row.append(label,value);$('inputs').append(row);});$('inputNote').textContent=r.name==='Custom recipe'?'Input ingredients are not calculated for custom recipes.':'Supply these ingredients continuously. Capacity figures assume all machines run at your selected clock.';$('source').href='https://satisfactory.wiki.gg/wiki/'+(r.name==='Custom recipe'?'Recipes':r.item.replaceAll(' ','_'));updateGraphics(r);window.currentResult={...v,recipe:r.name,machine:r.machine,clock};return window.currentResult;}catch(e){$('error').textContent=e.message;document.body.classList.add('invalid');window.currentResult=null;return null;}}
$('item').addEventListener('change',selectItem);['recipe','mode','amount','minutes','clock','base','customMachine'].forEach(id=>$(id).addEventListener('input',render));$('slider').addEventListener('input',()=>{$('clock').value=$('slider').value;render();});document.querySelectorAll('[data-clock]').forEach(b=>b.addEventListener('click',()=>{$('clock').value=b.dataset.clock;render();}));selectItem();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_machine_calculator',description:'Choose a built-in recipe, production rate and clock speed and return machine requirements.',inputSchema:{type:'object',properties:{recipe:{type:'string',enum:recipes.map(r=>r.name)},itemsPerMinute:{type:'number',minimum:0,maximum:1e9},clockPercent:{type:'number',minimum:1,maximum:250}},required:['recipe','itemsPerMinute','clockPercent'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const r=recipes.find(r=>r.name===input.recipe);if(!r)throw Error('Unknown recipe');calculate(r.rate,input.itemsPerMinute,input.clockPercent);$('item').value=r.item;selectItem();$('recipe').value=r.id;$('mode').value='rate';$('amount').value=input.itemsPerMinute;$('clock').value=input.clockPercent;return render();}})).catch(()=>{});}catch{}}
